SELECT 
FROM cps_room_check_record
WHERE room_id = #{roomId}
  AND submitted_at >= #{from} AND submitted_at < #{to}
ORDER BY submitted_at ASC

SELECT 
FROM cps_room_check_record
WHERE room_id = #{roomId}
  AND submitted_at >= #{from} AND submitted_at < #{to}
  AND record_status = 'JUDGED' AND judge_status = 'SUCCESS' AND score IS NOT NULL
ORDER BY submitted_at ASC

mapper.update:
UPDATE cps_room_check_record
SET judge_attempt = #{attempt}
WHERE id = #{id} AND judge_attempt < #{attempt}

mapper.select:
SELECT r.id AS id, r.room_code AS roomCode, r.room_name AS roomName, r.check_emp_no AS checkEmpNo, r.check_emp_name AS checkEmpName, r.record_status AS recordStatus, r.judge_status AS judgeStatus, r.judge_attempt AS judgeAttempt, r.score AS score, DATE_FORMAT(r.submitted_at, '%Y-%m-%d %H:%i:%s') AS submittedAt, (SELECT COUNT(*) FROM cps_room_check_record_item i WHERE i.record_id = r.id) AS itemCount, (SELECT COUNT(*) FROM cps_room_check_record_item i WHERE i.record_id = r.id AND i.final_result = 'FAIL') AS failCount, (SELECT COUNT(*) FROM cps_room_check_record_item i WHERE i.record_id = r.id AND i.final_modified_by IS NOT NULL) AS modifiedCount FROM cps_room_check_record r
AND r.record_status = #{recordStatus} AND r.judge_status = #{judgeStatus} AND r.room_code LIKE CONCAT('%', #{roomCode}, '%')
ORDER BY r.id DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM cps_room_check_record r

    AND r.record_status = #{recordStatus}
    AND r.judge_status = #{judgeStatus}
    AND r.room_code LIKE CONCAT('%', #{roomCode}, '%')
